import{_ as s,a0 as l,w as u,s as p,ao as n,I as a,x as o,a1 as i,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"故障排除提示：5 個最常見的 Linux 問題 | LCTT x X-CMD","titleTemplate":false,"description":"故障排除提示：5 個最常見的 Linux 問題 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"故障排除提示：5 個最常見的 Linux 問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"故障排除提示：5 個最常見的 Linux 問題 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170109 Troubleshooting tips for the 5 most common Linux issues","title":"故障排除提示：5 個最常見的 Linux 問題","tag":"201702","desc":""},"relativePath":"201702/20170109 Troubleshooting tips for the 5 most common Linux issues.md","filePath":"[post].md"}'),m={name:"201702/20170109 Troubleshooting tips for the 5 most common Linux issues.md"};function d(x,e,f,L,h,b){const t=l("Link");return u(),p("div",null,[e[16]||(e[16]=n('<h1 id="故障排除提示-5-個最常見的-linux-問題" tabindex="-1">故障排除提示：5 個最常見的 Linux 問題 <a class="header-anchor" href="#故障排除提示-5-個最常見的-linux-問題" aria-label="Permalink to “故障排除提示：5 個最常見的 Linux 問題”">​</a></h1><blockquote><p>瞭解如何解決Linux桌面用户遇到的最常見的問題</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/law/rh_003601_05_mech_osyearbook2016_containers_cc.png?itok=0ZEfXLEE" alt="5個linux最常見問題解決提示" title="Troubleshooting tips for the 5 most common Linux issues"></p><p>圖片：Opensource.com</p><p>儘管絕大多數用户如預期地成功安裝和操作了 Linux， 但不可避免地仍會有一些用户遇到問題。作為今年任務隊列裏的最後一篇文章，我認為在即將進入 2016 年時，總結一下人們所遇到的最常見的技術性的 Linux 問題會很有趣。我把這個問題發佈到了 LinuxQuestions.org（LQ） 和社交媒體，我分析了 LQ 的帖子情況之後，得到如下成果。</p><h3 id="_1、-wifi-驅動程序-特別是-broadcom-芯片" tabindex="-1">1、 Wifi 驅動程序（特別是 Broadcom 芯片） <a class="header-anchor" href="#_1、-wifi-驅動程序-特別是-broadcom-芯片" aria-label="Permalink to “1、 Wifi 驅動程序（特別是 Broadcom 芯片）”">​</a></h3><p>一般來説，Wifi 驅動程序，特別是 Broadcom 無線網卡，仍然是 Linux 面臨的最大的問題技術問題之一。在 LQ 上，2016 年有數以百計的帖子在討論這個話題，而且還有其他無數的地方也是。市場上有數十種 Broadcom 無線網卡可供使用，但為每一個發行版描述具體的排錯細節來已經超出了一篇文章的範疇，但是基本的故障排除步驟是相同的：</p><ul><li>通過使用 <code>lspci</code> 命令確定具體使用的 Broadcom 卡，以找出 PCI ID，</li><li>確定使用發行版是否支持該卡，</li><li>如果支持，找到正確的方法來使網卡工作。</li></ul><p>例如，如果有一個 <code>14e4:4315</code> PCI ID 的卡，並且系統為 Ubuntu，則應該知道 BCM4312 卡可以通過安裝 <code>firmware-b43-installer</code> 包來驅動。另一個選擇是在購買之前，研究好可用的 WiFi 卡，以確保您的發行版完全支持它。</p><h3 id="_2、-打印機驅動程序-特別是佳能和-lexmark" tabindex="-1">2、 打印機驅動程序（特別是佳能和 Lexmark） <a class="header-anchor" href="#_2、-打印機驅動程序-特別是佳能和-lexmark" aria-label="Permalink to “2、 打印機驅動程序（特別是佳能和 Lexmark）”">​</a></h3>',10)),a("p",null,[e[1]||(e[1]=o("打印機也是常有問題的，佳能和 Lexmark 被反覆提及遇到這種問題。如果您要購買一台新打印機，請在購買之前研究兼容性。但是，如果您從其他操作系統遷移，這可能沒得選擇。如果你正在做調研，",-1)),i(t,{href:"http://www.openprinting.org/printers"},{default:r(()=>[...e[0]||(e[0]=[o("OpenPrinting",-1)])]),_:1}),e[2]||(e[2]=o(" 資料庫和您的發行版的官方支持渠道是兩個最好的起點。請注意，您應確保設備的所有功能完全兼容，特別是如果它是個多功能產品。對佳能打印機的一個常見的抱怨是，驅動程序通常只能在非英語，甚至是很難找的網站上才有。",-1))]),e[17]||(e[17]=n('<blockquote><p>如果您購買的是新打印機，請在購買之前研究兼容性。</p></blockquote><h3 id="_3、-顯卡" tabindex="-1">3、 顯卡 <a class="header-anchor" href="#_3、-顯卡" aria-label="Permalink to “3、 顯卡”">​</a></h3><p>顯卡是一個微妙的話題，因為在 Linux 上顯卡可以非常好的簡單直觀的開箱即用。出現的問題是：顯卡加速器/3D 加速；最新的顯卡和最新顯示技術，如 NVIDIA Optimus 和 ATI 動態 GPU 切換；專有驅動程序的安裝和穩定性；能效管理；以及可靠的掛起和恢復。如果你不是一個遊戲玩家，也沒有別的需要高端圖形功能的需求，並且不是使用筆記本電腦，那麼你可能不必擔心這個。如果您正在尋找一台新的筆記本電腦，一定要在購買前研究好兼容性。如果你是一個遊戲玩家或需要最高端的圖形功能，你需要明確知道你的需求是什麼，然後開始你的研究。幸運的是，這種情況正在改善，Wayland 開始解決問題，2017 年情況應該會變得好一些。</p><h3 id="_4、-聲卡" tabindex="-1">4、 聲卡 <a class="header-anchor" href="#_4、-聲卡" aria-label="Permalink to “4、 聲卡”">​</a></h3><p>再次，對於簡單配置，聲卡非常容易設置並可以很可靠地在 Linux 上運行。一旦你買的是專業級產品，例如回聲消除、音頻路由，統一混合和其他複雜的配置，它可能就很快地每況愈下。我的建議是，如果你需要高端的實時音頻，請使用專用的音頻相關的發行版。</p><h3 id="_5、-安裝" tabindex="-1">5、 安裝 <a class="header-anchor" href="#_5、-安裝" aria-label="Permalink to “5、 安裝”">​</a></h3><p>有了這個包羅萬象的分類，本文幾乎保證是高質量的。也就是説，公平的説，我不知道 Linux 有普遍的安裝問題。絕大多數的安裝都按預期進行。Linux 支持多種硬件，安裝 Linux 機器上可能有近乎無限的硬件組合，不可避免會導致了某種情況下的例外情況。最終用户其實也很少安裝類似 Mac OS 或 Windows 這樣的其它系統，因為它們都是隨同新設備預安裝的。</p><blockquote><p>絕大多數的安裝都按預期進行。</p></blockquote><h3 id="前景光明" tabindex="-1">前景光明 <a class="header-anchor" href="#前景光明" aria-label="Permalink to “前景光明”">​</a></h3><p>其他提到的問題經常包括藍牙、掛起/恢復，HiDPI 和觸摸屏。您可能會看到這裏形成一個模式，本文中提到的大多數問題集中在桌面用户。如果你已經意識到了這點，這其實是有意義的。Linux 桌面使用率相對較低，導致結果是，用於發現和解決相關問題的測試和資源很少。隨着桌面使用量的增加，可以預期這些部分會改善。</p><p>在這方面，我認為最好提及的一個例子，曾經常常作為 Linux 的問題提出，但是反而最近很罕見：字體。幾年前，獲得高品質的抗鋸齒字體常常是個問題。但是，隨着現代發行版本的更新，它已成為常規。</p><p>你認為 2016 年最常見的 Linux 技術問題是什麼？ 請在評論中留言告訴我。</p><hr><p>作者簡介：</p><p><img src="https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/jeremy-garcia.jpg?itok=kqOMWJIg" alt=""></p><p>Jeremy Garcia - Jeremy Garcia is the founder of LinuxQuestions.org and an ardent but realistic open source advocate. Follow Jeremy on Twitter: @linuxquestions</p><hr>',17)),a("p",null,[e[4]||(e[4]=o("via: ",-1)),i(t,{href:"https://opensource.com/article/17/1/yearbook-linux-troubleshooting-tips"},{default:r(()=>[...e[3]||(e[3]=[o("https://opensource.com/article/17/1/yearbook-linux-troubleshooting-tips",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=o("作者：",-1)),i(t,{href:"https://opensource.com/users/jeremy-garcia"},{default:r(()=>[...e[5]||(e[5]=[o("Jeremy Garcia",-1)])]),_:1}),e[9]||(e[9]=o(" 譯者：",-1)),i(t,{href:"http://vicyu.net"},{default:r(()=>[...e[6]||(e[6]=[o("Vic020",-1)])]),_:1}),e[10]||(e[10]=o(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=o("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[o("Linux中國",-1)])]),_:1}),e[15]||(e[15]=o(" 榮譽推出",-1))])])}const g=s(m,[["render",d]]);export{c as __pageData,g as default};
